const assert = require('assert');
const path = require('path');
const deps = path.resolve('bokehjs/node_modules');
const jsdom = require(path.join(deps, 'jsdom'));
const document = jsdom.jsdom('<input id="date">');
global.window = document.defaultView;
global.document = document;
global.navigator = document.defaultView.navigator;
const Pikaday = require(path.join(deps, 'pikaday'));
describe('pinned Pikaday fork', function () {
  it('round trips a local calendar date', function () {
    const picker = new Pikaday({field: document.getElementById('date')});
    picker.setDate(new Date(2019, 9, 3), true);
    assert.strictEqual(picker.getDate().getFullYear(), 2019);
    assert.strictEqual(picker.getDate().getMonth(), 9);
    assert.strictEqual(picker.getDate().getDate(), 3);
    picker.destroy();
  });
});
